const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const seattle = ee.Geometry.Point([-122.3321, 47.6062]); // Center of Seattle
  const scale = 5000; // Resolution for analysis in meters

  const start2021 = '2021-09-01';
  const end2021 = '2021-11-30';
  const start2020 = '2020-09-01';
  const end2020 = '2020-11-30';
  const start2019 = '2019-09-01';
  const end2019 = '2019-11-30';

  // Define a function to get and process precipitation data for a given period
  const getPrecipitation = async (start, end, year) => {
    const collection = ee.ImageCollection('NOAA/PERSIANN_CDR')
      .filterDate(start, end)
      .filterBounds(seattle);

    const size = await collection.size().getInfo();
    if (size === 0) {
      console.log(`No images found for ${year}.`);
      return { value: null, size: 0 };
    }

    // Sum precipitation over the period
    const totalPrecipitation = collection.select('precipitation').sum();

    // Reduce region to get the mean precipitation value
    const stats = await totalPrecipitation.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: seattle,
      scale: scale,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    return { value: stats, size: size };
  };

  // 2. Data Acquisition & Check and 3. Processing
  let precip2021, precip2020, precip2019;

  try {
    console.log('Processing 2021 data...');
    precip2021 = await getPrecipitation(start2021, end2021, 2021);
    console.log('Processing 2020 data...');
    precip2020 = await getPrecipitation(start2020, end2020, 2020);
    console.log('Processing 2019 data...');
    precip2019 = await getPrecipitation(start2019, end2019, 2019);
  } catch (e) {
    console.log(`Error during data acquisition or processing: ${e.message}`);
    console.log('D'); // General error / memory issue / syntax
    return;
  }

  if (precip2021.size === 0 || precip2020.size === 0 || precip2019.size === 0) {
    console.log('C1'); // Empty Collection for one or more periods
    return;
  }

  // 4. Calculation and 5. Validation & Final Answer
  // Check for invalid results (NaN, None)
  if (precip2021.value === null || isNaN(precip2021.value) ||
      precip2020.value === null || isNaN(precip2020.value) ||
      precip2019.value === null || isNaN(precip2019.value)) {
    console.log('Calculation resulted in None/NaN values.');
    console.log('C3'); // Calculation Failure
    return;
  }

  console.log(`2021 (Sep-Nov) Total Rainfall: ${precip2021.value.toFixed(2)} mm (Images: ${precip2021.size})`);
  console.log(`2020 (Sep-Nov) Total Rainfall: ${precip2020.value.toFixed(2)} mm (Images: ${precip2020.size})`);
  console.log(`2019 (Sep-Nov) Total Rainfall: ${precip2019.value.toFixed(2)} mm (Images: ${precip2019.size})`);

  const largerThan2020 = precip2021.value > precip2020.value;
  const largerThan2019 = precip2021.value > precip2019.value;

  if (largerThan2020 && largerThan2019) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
